import {prepareArticleModel,readArticleRaw} from '../shared/article-import.js';
await prepareArticleModel('predictions','thinking-lab:predictions:v2');
import{mountShell}from'../shared/shell.js?v=0.22.0';
import{attachCardDrag}from'../shared/drag.js?v=0.21.0';
import{readStore,writeStore,downloadText}from'../shared/utils.js?v=0.24.0';
import{lineChart}from'../model-kit/chart.js?v=0.21.0';
import{create,validate,simulate,compareSharing,upgradeSettings,threshold,COUNT}from'./engine.js?v=0.21.0';
mountShell({active:'predictions'});
const app=document.querySelector('#app'),KEY='thinking-lab:predictions:v2';
const current=readStore(KEY,null),previous=readStore('thinking-lab:predictions:v1',null),saved=current||previous;
let legacy=current?.legacy||(!current?previous:null),s,baseline,week=Number.isFinite(saved?.week)?saved.week:0,past=[],destroy=()=>{},message='';
try{s=saved?.s?upgradeSettings(saved.s):create();baseline=saved?.baseline?upgradeSettings(saved.baseline):null;}catch{s=create();baseline=null;message='The saved settings could not be opened. The original save is unchanged.';}
if(!current&&previous)message='Your settings were copied to the corrected model. Both signal types now update at the same speed; previous results will change. The original save is retained and included in export.';
week=Math.min(39,Math.max(0,Math.round(week)));
const f=x=>x.toFixed(1);
function save(){if(!writeStore(KEY,{modelVersion:2,s,baseline,week,legacy}))message='Changes could not be saved in this browser. Export to keep this experiment.';}
function change(fn,msg='Same underlying pattern and noise sample replayed.'){
  past.push({s:structuredClone(s),baseline:structuredClone(baseline)});past=past.slice(-35);fn();validate(s);message=msg;save();render();
}
function render(){
  const focus=document.activeElement?.id;
  destroy();const r=simulate(s),b=baseline?simulate({...baseline,scenario:s.scenario,seed:s.seed}):null,row=r.history[week],matched=compareSharing(s);
  app.innerHTML=`<section class="surface"><div class="toolbar"><label for="scenario">Underlying price pattern</label><select id="scenario">${[['steady','Nearly steady'],['wave','A changing daily pattern'],['shift','A step in underlying demand']].map(([k,l])=>`<option value="${k}" ${s.scenario===k?'selected':''}>${l}</option>`).join('')}</select><button id="pin">Pin baseline</button><button id="undo" ${!past.length?'disabled':''}>Undo</button><button id="reset">Reset</button></div><p class="status" role="status">${message||'Both groups use the same update speed and noise amplitude. Shared users receive the same noisy observation; separate users receive individual ones.'}</p><div class="signal-board">${['common','private'].map(group=>`<section class="signal-group ${group}" data-drop-id="${group}"><h2>${group==='common'?'One shared forecast':'Separate estimates'}</h2><p class="hint">${s.common.filter(v=>v===(group==='common')).length} participants · drag a handle or activate it to switch.</p><div class="agents">${s.common.map((v,i)=>v===(group==='common')?`<article data-drag-id="${i}" class="agent"><button id="agent-${i}" data-drag-handle data-agent="${i}" aria-label="Participant ${i+1}, ${group} signal. Activate to switch."><span>${String(i+1).padStart(2,'0')}</span><strong>${row.actions[i]>=0?'↑':'↓'} ${Math.round(Math.abs(row.actions[i])*100)}%</strong></button><small>Threshold ${f(threshold(s,i))}</small></article>`:'').join('')}</div></section>`).join('')}</div><div class="toolbar"><button id="all-common" data-all="common">All share</button><button id="all-mixed" data-all="mixed">Half share</button><button id="all-private" data-all="private">All separate</button></div></section>
  <div class="split"><section class="surface"><h2>Watch the feedback</h2><div class="key"><span><b></b>Realised price</span><span><b></b>Mean forecast used</span><span>Dashed: underlying / pinned</span></div><div class="chart" role="img" aria-label="Realised price, mean forecast used and underlying price over 40 rounds">${lineChart([{values:r.history.map(x=>x.price)},{values:r.history.map(x=>x.meanSignal),color:'var(--warn)'},{values:r.history.map(x=>x.base),color:'var(--muted)',dashed:true},...(b?[{values:b.history.map(x=>x.price),color:'var(--muted)',dashed:true}]:[])],{min:-20,max:120,cursor:week,labels:['Round 1','Round 40']})}</div><div class="field"><label for="week">Inspect round <output>${week+1}</output></label><input id="week" type="range" min="0" max="39" value="${week}"></div><p class="round-info">Mean forecast ${f(row.meanSignal)} → mean response ${f(row.mean*100)}% → realised ${f(row.price)}. Underlying price without response: ${f(row.base)}.</p></section>
  <section class="surface"><h2>Change one assumption</h2><div class="fields">${[['reaction','Update speed · both groups',.05,1,.05],['noise','Observation noise · both groups',0,20,1],['sensitivity','Response to price difference',.1,3,.1],['diversity','Spread of willingness thresholds',0,30,1],['impact','Price impact at full response',0,50,1],['initial','Starting estimate · both groups',0,100,1]].map(([k,l,min,max,step])=>`<div class="field"><label for="${k}">${l} <output>${f(s[k])}</output></label><input data-param="${k}" id="${k}" type="range" min="${min}" max="${max}" step="${step}" value="${s[k]}"></div>`).join('')}</div><div class="toolbar"><button id="sample">Try another noise sample</button><span class="hint">Sample ${s.seed}</span><button id="no-noise">Remove noise</button></div><p class="hint">With no noise and identical starting estimates, sharing alone changes nothing. Increasing speed can create unstable feedback in either group.</p></section></div>
  <section class="surface"><h2>Isolate signal sharing</h2><p>Two replays change only who shares a signal. Both keep update speed ${f(s.reaction)}, noise ${f(s.noise)}, sample ${s.seed}, thresholds, starting estimates and the underlying pattern fixed.</p><div class="table-scroll"><table><caption class="sr-only">Matched sharing comparison</caption><thead><tr><th>Replay</th><th>Mean price change</th><th>Forecast error per participant</th><th>Price range</th></tr></thead><tbody>${[['All share',matched.shared],['All separate',matched.separate]].map(([label,result])=>`<tr><th>${label}</th><td>${f(result.oscillation)}</td><td>${f(result.error)}</td><td>${f(result.range)}</td></tr>`).join('')}</tbody></table></div><p class="hint">One noise sample is an illustration, not an average effect. Try other samples and assumptions. These scores do not rank trading strategies.</p></section>
  <section class="metrics"><div class="metric"><span>Mean change between rounds</span><strong>${f(r.oscillation)}</strong><small>${b?`${f(b.oscillation)} in baseline`:'Price units; not a risk estimate'}</small></div><div class="metric"><span>Forecast error per participant</span><strong>${f(r.error)}</strong><small>Mean absolute error after responses change price</small></div><div class="metric"><span>Realised price range</span><strong>${f(r.range)}</strong><small>Maximum minus minimum</small></div><div class="metric"><span>Common signal users</span><strong>${s.common.filter(Boolean).length}/${COUNT}</strong><small>All see the same published estimate</small></div></section>
  <details><summary>Mechanism, timing and limits</summary><p>Each participant has a willingness threshold centred on 50. Its action = clamp(sensitivity × (threshold − signal) / 20, −1,+1). Positive means charging; negative means discharge. Realised price = underlying price + price impact × mean action. Every estimate then moves toward that realised price plus observation noise, at the same update speed. No estimate sees the next underlying price.</p><p>Noise has the same uniform range in both groups. Shared users receive one common noise draw; private sources have independent pseudorandom draws from the same seeded sample. All estimates start equal. Willingness thresholds are separate from information noise. Replaying holds the draws fixed; changing signal sharing can still change future realised prices through behaviour.</p><p>These hypothetical clearing rounds omit state of charge, inventory, network limits, bids and learning. The chart is a mechanism sketch, not a battery-market forecast. Pinned runs reuse the current underlying pattern and noise sample but retain their other settings; the matched table changes sharing only.</p></details><p class="local-note">Plan and baseline save in this browser. ↑ charge adds demand; ↓ discharge adds supply.</p>`;
  bind();destroy=attachCardDrag({root:app,onDrop:({itemId,dropId})=>change(()=>s.common[+itemId]=dropId==='common','Signal assignment changed; update speed and noise amplitude stayed fixed.')});
  if(focus)document.getElementById(focus)?.focus({preventScroll:true});
}
function bind(){
  app.querySelectorAll('[data-agent]').forEach(el=>el.onclick=()=>change(()=>s.common[+el.dataset.agent]=!s.common[+el.dataset.agent]));
  app.querySelectorAll('[data-all]').forEach(el=>el.onclick=()=>change(()=>s.common=s.common.map((_,i)=>el.dataset.all==='common'||el.dataset.all==='mixed'&&i<12)));
  app.querySelectorAll('[data-param]').forEach(el=>el.onchange=()=>{const k=el.dataset.param,v=+el.value;change(()=>s[k]=v);});
  document.querySelector('#scenario').onchange=ev=>{const v=ev.target.value;change(()=>s.scenario=v);};
  document.querySelector('#week').onchange=ev=>{week=+ev.target.value;save();render();};
  document.querySelector('#pin').onclick=()=>change(()=>baseline=structuredClone(s),'Baseline pinned. Underlying pattern and noise sample stay matched.');
  document.querySelector('#sample').onclick=()=>change(()=>s.seed=s.seed%9999+1,'A new noise sample applies to the current, pinned and matched runs.');
  document.querySelector('#no-noise').onclick=()=>change(()=>s.noise=0,'Without noise, shared and separate estimates evolve identically.');
  document.querySelector('#undo').onclick=()=>{const p=past.pop();if(p){s=p.s;baseline=p.baseline;save();render();}};
  document.querySelector('#reset').onclick=()=>change(()=>s=create(),'Default feedback restored.');
}
document.querySelector('#export').onclick=()=>downloadText('prediction-feedback.md',`# When predictions change behaviour\n\nModel 2: matched update rates and noise amplitudes. Fictional repeated clearing rounds, without state of charge or financial calibration. Pinned runs use the current underlying pattern and noise sample.\n\n\`\`\`json\n${JSON.stringify({modelVersion:2,settings:s,baseline,result:simulate(s),matched:compareSharing(s),baselineResult:baseline?simulate({...baseline,scenario:s.scenario,seed:s.seed}):null,previousModelSave:legacy},null,2)}\n\`\`\`\n`,'text/markdown');
render();
